return function(Plasma)
	local create = Plasma.create
	return Plasma.widget(function(text, options)
		options = options or {}
		local style = Plasma.useStyle()
		local clicked, setClicked = Plasma.useState(false)
		local refs = Plasma.useInstance(function(ref)
			local label = create("TextButton", {
				TextSize = 22,
				AutomaticSize = Enum.AutomaticSize.XY,
				Text = "",
				BackgroundTransparency = 0,
				BackgroundColor3 = style.bg2,
				TextColor3 = Color3.new(1, 1, 1),
				Font = Enum.Font.GothamBold,
				create("UIPadding", {
					PaddingTop = UDim.new(0, 8),
					PaddingBottom = UDim.new(0, 8),
					PaddingLeft = UDim.new(0, 8),
					PaddingRight = UDim.new(0, 8),
				}),
				create("UICorner"),

				Activated = function()
					setClicked(true)
				end,
			})

			ref.label = label

			return label
		end)
		refs.label.Text = text
		refs.label.Size = options.width and UDim2.fromOffset(options.width, 0) or UDim2.fromScale(0, 0)
		refs.label.TextXAlignment = options.align or Enum.TextXAlignment.Center
		refs.label.BackgroundColor3 = options.bg or style.bg2

		local handle = {
			clicked = function()
				if clicked then
					setClicked(false)
					return true
				end
				return false
			end,
		}
		return handle
	end)
end
